INSERT INTO parks (name, lat, lon, region) SELECT 'Hong Kong Disneyland', 22.313, 114.0413, 'Hong Kong' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Hong Kong Disneyland');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Big Grizzly Mountain Runaway Mine Cars', 'Hong Kong Disneyland', 'Steel', 'Vekoma', 'Vekoma Family Coaster', NULL, 34.8, 3605.6, 0, NULL, 2012, '2012-07-13', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Big Grizzly Mountain Runaway Mine Cars' AND park = 'Hong Kong Disneyland');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Big Grizzly Mountain Runaway Mine Cars' AND c.park = 'Hong Kong Disneyland' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
